// Flatten to "group.field" keys so content('about.title') can find its definition.
$fields = [];
foreach ($groups as $group => $definition) {
    foreach ($definition['fields'] as $name => $field) {
        $fields[$group.'.'.$name] = $field + ['group' => $group];
    }
}

